import {locales,translate} from './i18n.js';
import {icon} from './icons.js';
import {navigationText} from './navigation-copy.js';
import {boardMarkup,sideFormMarkup,sideResultMarkup} from './board.js';
import {todayMarkup,reportSheetMarkup,reportBadge} from './today.js';
import {addRide,drawShareCard,gameMarkup,newStamps} from './game.js';
import {chip,homeLineMarkup,routeBoardMarkup,routeJumpMarkup} from './board.js';
import {homeMarkup} from './home.js';
import {mapMarkup,destroyMap,mountMap,mapAction,locateOnMap,updateMapData} from './map.js';
import {createBusChatUI} from './bus-chat.js';
import {createPlaceLookup,attachPlaceAutocomplete} from './place-autocomplete.js';
const read=(k,v)=>{try{return JSON.parse(localStorage.getItem(k))??v;}catch{return v;}};
const state={locale:read('jejubus.locale','ko'),favorites:read('jejubus.savedRoutes',[]),view:'explore',pane:'search',mode:'destination',sort:'fastest',query:'',origin:'',from:null,to:null,category:'all',posts:[],status:{},results:null,route:null,stop:null,routeStops:[],vehicles:[],arrivals:[],paths:[],path:null,lines:[],error:null,busy:false,context:'general',communityQuery:'',communityError:false,noTransfers:false,liveError:null,liveAt:null,vehicleAt:null,focusKey:null,reviewSummary:{},notices:{}};
if(!locales[state.locale])state.locale='ko';if(!Array.isArray(state.favorites))state.favorites=[];
state.favorites=state.favorites.filter(r=>r&&typeof r.id==='string'&&typeof r.number==='string').slice(0,50);
const t=(key,values)=>translate(state.locale,key,values),e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const local=v=>v&&typeof v==='object'?(v[state.locale]||v.ko):v;
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
let toastTimer,detailPost,postDraft,searchVersion=0,selectionVersion=0,polling=new Set();
let disposePlaceAutocomplete=()=>{};
function persist(k,v){try{localStorage.setItem(k,JSON.stringify(v));}catch{toast(t('storageError'));}}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
async function api(url,options={}){const res=await fetch(url,{...options,headers:{'Content-Type':'application/json',...options.headers}});const body=await res.json();if(!res.ok)throw Object.assign(Error(body.error),{key:body.error,status:res.status});return body;}
const lookupPlaces=createPlaceLookup(async query=>(await api(`/api/places?q=${encodeURIComponent(query)}`)).places);
const postOptions=body=>({method:'POST',body:JSON.stringify(body)});
const setupLink=()=>state.status.setupAvailable?`<a class="text-btn" href="/setup">${t('setup')} ${icon('arrow')}</a>`:'';
const errorBox=key=>`<div class="notice error-card" role="alert">${icon('info')}<p>${e(t(key||'connectionError'))}</p>${setupLink()}<button class="text-btn" data-action="retry-search">${t('retry')}</button></div>`;
const time=at=>at?new Date(at).toLocaleTimeString(state.locale,{hour:'2-digit',minute:'2-digit',second:'2-digit'}):'—';
const sorted=()=>[...state.paths].filter(p=>!state.noTransfers||p.transfers===0).sort((a,b)=>(state.sort==='distance'?(a.totalMeters??Infinity)-(b.totalMeters??Infinity):state.sort==='walking'?a.walkingMeters-b.walkingMeters:state.sort==='transfers'?a.transfers-b.transfers:a.totalMinutes-b.totalMinutes)||a.totalMinutes-b.totalMinutes);
const busChatUI=createBusChatUI({dialog,t,request:api,getStatus:()=>state.status,getContext:()=>({...(state.route?{route:{id:state.route.id,name:state.route.number}}:{}),...(state.stop?{stop:{id:state.stop.id,name:state.stop.name}}:{}),...(state.from?{from:state.from}:{}),...(state.to?{to:state.to}:{})}),onLogin:showLogin,onRoute:async(id,number)=>{state.route={id,number:number||id};state.view='map';state.mode='route';await selectRoute(id);}});
function navMarkup(){const views=['home','map','explore','today','favorites'];return ['boardTab','findTab','explore','todayTab','jejuTab'].map((key,i)=>`<button class="nav-item ${state.view===views[i]?'active':''}" data-view="${views[i]}">${icon(['star','bus','search','info','leaf'][i])}<span>${t(key)}${views[i]==='today'&&state.todayData?.notices?.length?'<i class="nav-dot" aria-hidden="true"></i>':''}</span></button>`).join('')+`<button class="nav-item" data-action="ai-chat">${icon('sparkles')}<span>${t('aiChat')}</span></button>`;}
function contextName(value){if(value==='general')return t('general');if(value.startsWith('route:')){const r=[state.route,...state.favorites,...(state.results?.kind==='routes'?state.results.items:[])].find(r=>r&&`route:${r.id}`===value);return `${t('route')} ${r?.number||value.slice(6)}`;}return `${t('stopMode')} ${state.stop&&value===`stop:${state.stop.id}`?state.stop.name:value.slice(5)}`;}
function contexts(){return [...new Set(['general',state.context,...state.favorites.map(r=>`route:${r.id}`),...(state.route?[`route:${state.route.id}`]:[]),...(state.stop?[`stop:${state.stop.id}`]:[])])];}
function routeCard(r){const saved=state.favorites.some(s=>s.id===r.id);return `<article class="journey-card ${state.route?.id===r.id?'selected':''}"><button class="journey-main" data-route="${e(r.id)}">${chip(r.number,e,t)}<h3>${e(r.start||'')} ${r.end?'→':''} ${e(r.end||'')}</h3></button><button class="save-route ${saved?'is-saved':''}" data-save="${e(r.id)}" aria-label="${t(saved?'saved':'save')} ${e(r.number)}" aria-pressed="${saved}">${icon('star')}</button></article>`;}
function pathCard(p){return `<article class="journey-card ${state.path?.id===p.id?'selected':''}"><button class="journey-main" data-path="${e(p.id)}"><div class="journey-tags">${p.legs.filter(l=>l.type==='bus').flatMap(l=>l.routes).map(r=>chip(r.number,e,t)).join('')}</div><div class="journey-time"><strong>${Math.ceil(p.totalMinutes)}</strong><span>${t('min')}</span></div><div class="journey-meta">${t(p.transfers?'transferCount':'transferNone',{n:p.transfers})} · ${t('walk')} ${Math.round(p.walkingMeters)}m${p.totalMeters===null||p.totalMeters===undefined?'':` · ${(p.totalMeters/1000).toFixed(1)}km`}</div><p class="journey-foot">${e(state.journeySource)} · ${t('receivedAt',{time:time(state.journeyAt)})}</p></button><button class="detail-link" data-path-detail="${e(p.id)}">${t('routeDetail')}${icon('arrow')}</button></article>`;}
const stars=n=>'★'.repeat(n)+'☆'.repeat(5-n);
function activeContext(){const {stop,route}=state;if(stop)return {id:`stop:${stop.id}`,name:stop.name,kind:'stop',item:stop};if(route)return {id:`route:${route.id}`,name:route.number,kind:'route',item:route};return null;}
function directionsUrl(stop){const name=encodeURIComponent(stop.name);return Number.isFinite(stop.lat)&&Number.isFinite(stop.lng)?`https://map.kakao.com/link/to/${name},${stop.lat},${stop.lng}`:`https://map.kakao.com/link/search/${name}`;}
function contextTools(){const c=activeContext();if(!c)return '';const s=state.reviewSummary[c.id];const list=state.notices[c.id]||[];return `${list.length?`<div class="route-notices"><strong>${t('noticeHeading')}</strong>${list.map(n=>`<article><b>${e(n.title)}</b><p>${e(n.body)}</p>${n.startsOn||n.endsOn?`<small>${e(n.startsOn||'')} ~ ${e(n.endsOn||'')}</small>`:''}${n.sourceUrl?`<a href="${e(n.sourceUrl)}" target="_blank" rel="noopener noreferrer">${t('noticeOpen')}</a>`:''}</article>`).join('')}</div>`:''}<div class="context-tools"><button data-action="reviews">${icon('star')}${t('reviews')}${s?.count?` ★${s.average} (${s.count})`:''}</button><button data-action="inquiry">${icon('chat')}${t('inquiry')}</button><button data-action="share">${icon('external')}${t('share')}</button>${c.kind==='stop'?`<a href="${e(directionsUrl(c.item))}" target="_blank" rel="noopener noreferrer">${icon('pin')}${t('kakaoDirections')}</a>`:''}</div>`;}
async function loadReviewSummary(){const c=activeContext();if(!c)return;try{const [{summary},{notices}]=await Promise.all([api(`/api/reviews?context=${encodeURIComponent(c.id)}`),api(`/api/notices?context=${encodeURIComponent(c.id)}`)]);state.reviewSummary[c.id]=summary;state.notices[c.id]=notices;const el=document.querySelector('.context-tools');if(el&&activeContext()?.id===c.id){document.querySelector('.route-notices')?.remove();el.outerHTML=contextTools();}}catch{}}
function liveMarkup(){if(!state.route&&!state.stop)return '';return `<section class="live-details"><div class="results-heading"><strong>${e(state.stop?.name||state.route?.number)}</strong><button data-action="refresh-live" aria-label="${t('refresh')}">${icon('refresh')}</button></div>${contextTools()}${state.stop?`<button class="save-stop" data-action="save-stop">${t(myStops().some(s=>s.id===state.stop.id)?'unsaveStop':'saveStop')}</button> <button class="save-stop" data-action="home-stop">${t(stored('jb.homeStop',null)?.id===state.stop.id?'homeUnset':'homeSet')}</button><div id="home-line">${state.homeLine?homeLineMarkup(state.homeLine,'',e,t):''}</div>${sideFormMarkup(state.sideTo,state.side,e,t,state.board)}`:''}<div id="live-content">${liveContent()}</div><div id="route-board">${routeBoardView()}</div></section>`;}
function liveContent(){return `${state.liveError?`<p class="live-stale" role="status">${t(state.liveError==='quotaReached'?'boardQuota':'boardLost')} <a href="https://bus.jeju.go.kr/" target="_blank" rel="noopener noreferrer">${t('boardOfficial')}</a></p>`:''}<p class="source-time">TAGO · ${t('receivedAt',{time:time(state.liveAt)})}</p>${state.route?`<p>${state.vehicles.length?t('vehicles',{n:state.vehicles.length}):t('noVehicles')}</p>${routeFacts()}`:''}${state.stop?(state.board?boardMarkup(state.board,e,t,{reports:state.boardReports||[],badge:reportBadge,game:gameOn()}):`<h3>${t('arrivals')}</h3><p class="muted">${t('noArrival')}</p>`):''}`;}
function routeFacts(){const g=state.routeGroup;if(!g||g.no!==state.route?.number)return '';const c=state.liveCoverage;return `<p class="route-facts">${c?.total>1?`${t('liveCovers',{n:c.total})}<br>`:''}${c?.partial?`${t('livePartial')}<br>`:''}<a href="${e(g.scheduleUrl)}" target="_blank" rel="noopener noreferrer">${t('boardSchedule')}</a></p>`;}
function moreResults(){return state.results?.hasMore?`<button class="text-btn load-more" data-action="more-results">${t('moreResults')}</button>`:'';}
function resultMarkup(){
 if(state.busy)return `<div class="empty-state" role="status">${t('loading')}</div>`;
 if(state.error)return errorBox(state.error);
 if(state.results?.kind==='places')return `<div class="results-heading">${t('choosePlace')} · ${t(state.results.target)}</div>${state.results.items.length?state.results.items.map((p,i)=>`<button class="place-result" data-place="${i}">${icon('pin')}<span><strong>${e(p.name)}</strong><small>${e(p.address)}</small></span>${icon('chevron')}</button>`).join(''):`<div class="empty-state">${t('noResults')}</div>`}${moreResults()}`;
 if(state.results?.kind==='routes')return `${state.results.items.length?state.results.items.map(routeCard).join(''):`<div class="empty-state">${t('noResults')}</div>`}${moreResults()}${liveMarkup()}`;
 if(state.results?.kind==='stops')return `${state.results.items.length?state.results.items.map(s=>`<button class="place-result" data-stop="${e(s.id)}">${icon('pin')}<span><strong>${e(s.name)}</strong><small>${e(s.number)}${s.distanceMeters===undefined?'':` · ${s.distanceMeters}m`}</small></span>${icon('chevron')}</button>`).join(''):`<div class="empty-state">${t('noResults')}</div>`}${moreResults()}${liveMarkup()}`;
 if(state.results?.kind==='journeys'){const items=sorted();return `<div class="results-heading">${t('recommended')} <small>${items.length}</small></div><p class="muted estimate-note">${t('estimated')}</p>${items.length?items.map(pathCard).join(''):`<div class="empty-state">${t('noResults')}</div>`}`;}
 if(state.view==='map')return `<div class="start-card"><span class="eyebrow">LIVE BUSES</span><h3>${t('liveRouteHelp')}</h3><p class="muted">${t('liveRefreshHelp')}</p></div>${liveMarkup()}`;
 return `<div class="start-card"><span class="eyebrow">PLAN YOUR RIDE</span><h3>${t('initialHelp')}</h3><div class="connection-chips">${['transit','places','routing'].map(k=>`<span class="${state.status.capabilities?.[k]?'connected':''}">${t({transit:'realtime',places:'destinationMode',routing:'explore'}[k])} · ${t(!state.status.capabilities?'loading':state.status.capabilities[k]?'ready':'dataPending')}</span>`).join('')}</div>${setupLink()}<button class="text-btn" data-action="show-map">${t('chooseOnMap')} ${icon('arrow')}</button></div>${moreResults()}${liveMarkup()}`;
}
function postCard(p,wide=false){return `<article class="post-card ${wide?'wide':''}"><div class="post-author"><span class="avatar avatar-${e(p.category)}">${e(p.author?.slice(0,1)||'J')}</span><span><strong>${e(p.author)}</strong><small>${Date.now()-p.created<60000?t('justNow'):t('minutesAgo',{n:Math.max(1,Math.floor((Date.now()-p.created)/60000))})}</small></span><span class="post-route">${p.sample?t('sample')+' · ':''}${e(p.contextName||contextName(p.route))}</span></div><button class="post-open" data-post="${e(p.id)}"><span class="category category-${e(p.category)}">${t(p.category)}</span><h3>${e(local(p.title))}</h3>${wide?`<p>${e(local(p.body))}</p>`:''}</button><div class="post-footer"><button data-post="${e(p.id)}">${icon('chat')}${t('replyCount',{n:p.replies})}</button><button data-like="${e(p.id)}" class="${p.liked?'liked':''}" aria-label="${t('helpful')}" aria-pressed="${p.liked}">${icon('heart')} ${p.likes}</button></div></article>`;}
function filteredPosts(){const q=state.communityQuery.toLocaleLowerCase();return state.posts.filter(p=>(state.category==='all'||p.category===state.category)&&(state.context==='general'||p.route===state.context||(state.context.startsWith('route:')&&p.routeNo&&p.routeNo===state.route?.number))&&(!q||`${local(p.title)} ${local(p.body)}`.toLocaleLowerCase().includes(q)));}
function communityMarkup(){const items=filteredPosts();return `<div class="community-heading"><span class="eyebrow">COMMUNITY</span><div><h2>${t(state.context==='general'?'latestTalk':'activeContext')}</h2><button class="compose" data-action="reload-posts" aria-label="${t('refresh')}">${icon('refresh')}</button><button class="compose" data-action="compose" aria-label="${t('write')}">${icon('pencil')}</button></div><p>${e(contextName(state.context))} · ${t('talkSub')}</p><label class="sr-only" for="community-query">${t('searchCommunity')}</label><input id="community-query" placeholder="${t('searchCommunity')}" value="${e(state.communityQuery)}"><select id="context-filter" aria-label="${t('context')}">${contexts().map(c=>`<option value="${e(c)}" ${state.context===c?'selected':''}>${e(contextName(c))}</option>`).join('')}</select></div><div class="community-tabs">${['all','question','update','concern','tip'].map(c=>`<button class="${state.category===c?'active':''}" data-category="${c}">${t(c)}</button>`).join('')}</div><div class="post-list">${state.communityError?errorBox('communityError'):items.length?items.map(p=>postCard(p,state.view==='community')).join(''):`<div class="empty-state">${icon('chat')}<h3>${t('noPosts')}</h3><p>${t('firstPost')}</p></div>`}</div><div class="community-bottom"><p>${icon('info')}${t('communityNote')}</p><button class="write-button" data-action="compose">${icon('plus')}${t('write')}</button>${state.status.user?.admin?`<button class="text-btn" data-action="admin">${t('admin')}</button>`:''}${state.view!=='community'?`<button class="text-btn" data-view="community">${t('more')}${icon('arrow')}</button>`:''}</div>`;}
function liveMapSummary(){return `<strong>${e(state.route?`${t('route')} ${state.route.number}`:t('liveMap'))}</strong><span>${state.route?(state.vehicleAt?t('vehicles',{n:state.vehicles.length}):t(state.liveError?'positionUnavailable':'loading')):t('liveRouteHelp')}</span>${state.route?`<small>${state.liveError?t('stale'):'TAGO'} · ${t('receivedAt',{time:time(state.vehicleAt)})}</small>`:''}`;}
function routeLine(){if(!state.route)return [];const pts=[...state.routeStops].filter(s=>Number.isFinite(Number(s.lat))&&Number.isFinite(Number(s.lng))).sort((a,b)=>(Number(a.order)||0)-(Number(b.order)||0));return pts.length>1?[pts]:[];}
function mapData(){return {live:state.view==='map',routeNumber:state.route?.number,stops:state.routeStops.length?state.routeStops:state.results?.kind==='stops'?state.results.items:state.stop?[state.stop]:[],vehicles:state.vehicles,lines:state.lines.length?state.lines:routeLine(),from:state.mode==='destination'?state.from:null,to:state.mode==='destination'?state.to:null,focusKey:state.focusKey};}
function render(){
 const focused=document.activeElement,editing=focused&&['origin-input','search-input'].includes(focused.id)?{id:focused.id,start:focused.selectionStart,end:focused.selectionEnd}:null;
 disposePlaceAutocomplete();disposePlaceAutocomplete=()=>{};
 destroyMap();document.documentElement.lang=state.locale==='zh'?'zh-CN':state.locale;document.title=`${t('brand')} · ${t('tagline')}`;const dark=document.documentElement.dataset.theme==='dark';
 app.innerHTML=`<header class="site-header"><a class="brand" href="/"><span class="brand-icon">${icon('bus')}</span><span>${t('brand')}<small>JEJU BUS</small></span></a><nav class="desktop-nav">${navMarkup()}</nav><div class="header-tools"><button class="theme-toggle" role="switch" aria-checked="${dark}" aria-label="${t('themeLabel')}" data-action="theme"><span class="toggle-track"><span class="toggle-thumb">${icon(dark?'moon':'sun')}</span></span></button><label class="language-picker">${icon('globe')}<span class="sr-only">${t('language')}</span><select id="language">${Object.entries(locales).map(([id,name])=>`<option value="${id}" ${id===state.locale?'selected':''}>${name}</option>`).join('')}</select>${icon('down')}</label><button class="login-button" aria-label="${e(state.status.user?.name||t('login'))}" data-action="${state.status.user?'account':'login'}">${state.status.user?icon('user'):'<span class="google-mark">G</span>'}<span>${e(state.status.user?.name||t('login'))}</span></button></div></header>
 <main id="main" class="workspace view-${state.view} mobile-${state.pane}"><aside class="search-panel"><div class="search-intro"><span class="eyebrow">YOUR NEXT STOP</span><h1>${t(state.view==='map'?'liveMap':'hero')}</h1><p>${t(state.view==='map'?'liveRouteHelp':'heroSub')}</p></div><div class="search-types">${['destination','route','stop'].map(m=>`<button data-mode="${m}" class="${state.mode===m?'active':''}" aria-pressed="${state.mode===m}">${t(m+'Mode')}</button>`).join('')}</div>
 <form id="search-form"><div class="search-fields">${state.mode==='destination'?`<label class="origin-field"><span class="origin-dot"></span><span class="sr-only">${t('origin')}</span><input id="origin-input" autocomplete="off" value="${e(state.origin)}" placeholder="${t('originSample')}"><button type="button" data-action="find-origin" aria-label="${t('origin')} ${t('searchShort')}">${icon('search')}</button><button type="button" class="locate-input" data-action="geolocate" aria-label="${t('locate')}">${icon('locate')}</button></label>`:''}<label class="destination-field">${icon('pin')}<span class="sr-only">${t(state.mode+'Mode')}</span><input id="search-input" autocomplete="off" value="${e(state.query)}" placeholder="${t(state.mode+'Placeholder')}"><button type="button" class="clear-input" data-action="clear-search" aria-label="${t('close')}">${icon('close')}</button></label></div><button class="search-button" type="submit" ${state.busy?'disabled':''}>${icon('search')}${t(state.mode==='destination'?'search':'searchShort')}${icon('arrow')}</button></form>
 <div class="search-actions">${state.mode==='destination'?`<button data-action="swap" aria-label="${t('swap')}">${icon('swap')}${t('swap')}</button><button data-action="intent" title="${t('naturalHelp')}">${icon('sparkles')}${t('intentRules')}</button>`:`<button data-action="nearby">${icon('locate')}${t('nearby')}</button>`}<button data-action="show-map">${icon('map')}${t(state.view==='map'?'liveMap':'chooseOnMap')}</button></div>
 <div class="sort-tabs">${['fastest','distance','walking','transfers'].map(s=>`<button class="${state.sort===s?'active':''}" data-sort="${s}">${t(s)}</button>`).join('')}</div><label class="check-label direct-filter"><input type="checkbox" id="direct-only" ${state.noTransfers?'checked':''}>${t('noTransfersFilter')}</label><div class="journey-list" aria-live="polite">${resultMarkup()}</div><div class="search-footer"><a href="https://bus.jeju.go.kr" target="_blank" rel="noopener noreferrer">${t('official')}${icon('external')}</a>${state.status.channelId?`<a href="https://pf.kakao.com/${e(state.status.channelId)}/chat" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">${t('kakaoConsult')}${icon('external')}</a>`:''}${setupLink()}<small>${t('source')}</small></div></aside>
 <section class="map-panel" aria-label="${t('liveMap')}">${state.view==='home'?homeMarkup({homeStop:stored('jb.homeStop',null),stops:myStops(),boards:state.homeBoards,favorites:state.favorites,alerts:todayView()?.mine?.length||0,guide:guideOpen()},e,t):state.view==='today'?todayMarkup(todayView(),e,t,{locale:state.locale,navigationLabel:navigationText(state.locale,'navigation')}):state.view==='favorites'?`<div class="favorites-board"><button class="game-on" data-action="simple-toggle">${t(stored('jb.simple',false)?'simpleOff':'simpleOn')}</button>${gameOn()?gameMarkup(storedRides(),e,t):`<button class="game-on" data-action="game-on">${t('gameOn')}</button>`}<div class="favorite-hero">${icon('star')}<span class="eyebrow">MY BUS</span><h2>${t('favoritesTitle')}</h2><p>${t('favoritesSub')}</p></div>${state.favorites.length?state.favorites.map(routeCard).join(''):`<div class="empty-state"><h3>${t('noFavorites')}</h3><p>${t('addFavorites')}</p></div>`}</div>`:mapMarkup({t,live:state.view==='map',summary:liveMapSummary()})}</section><aside class="community-panel">${communityMarkup()}</aside></main><nav class="mobile-nav">${navMarkup()}</nav>`;
 document.querySelector('#language').addEventListener('change',ev=>{state.locale=ev.target.value;persist('jejubus.locale',state.locale);render();});
 document.querySelector('#search-form').addEventListener('submit',ev=>{ev.preventDefault();search();});
 document.querySelector('#search-input').addEventListener('input',ev=>{state.query=ev.target.value;state.to=null;});
 document.querySelector('#origin-input')?.addEventListener('input',ev=>{state.origin=ev.target.value;state.from=null;});
 if(state.mode==='destination'){
  const disposers=[['origin','#origin-input'],['destination','#search-input']].map(([target,selector])=>attachPlaceAutocomplete(document.querySelector(selector),{target,t,lookup:lookupPlaces,isSelected:()=>!!state[target==='origin'?'from':'to'],onSelect:place=>selectSuggestedPlace(target,place)}));
  disposePlaceAutocomplete=()=>disposers.forEach(dispose=>dispose());
 }
 document.querySelector('#direct-only').addEventListener('change',async ev=>{state.noTransfers=ev.target.checked;await selectPath(sorted()[0],false);render();});
 document.querySelector('#context-filter').addEventListener('change',ev=>{state.context=ev.target.value;render();});
 document.querySelector('#community-query').addEventListener('input',ev=>{state.communityQuery=ev.target.value;const items=filteredPosts();document.querySelector('.post-list').innerHTML=items.length?items.map(p=>postCard(p,state.view==='community')).join(''):`<div class="empty-state">${t('noPosts')}</div>`;});
 mountMap({t,data:mapData(),onPick:state.view==='map'?null:pickPoint,onStop:chooseStop});
 if(editing){const input=document.getElementById(editing.id);if(input){input.focus({preventScroll:true});input.setSelectionRange(editing.start,editing.end);}}
}
const coordinateText=q=>{const match=String(q).match(/^\s*(33(?:\.\d+)?|34(?:\.\d+)?)\s*,\s*(12[567](?:\.\d+)?)\s*$/);return match?{lat:Number(match[1]),lng:Number(match[2]),name:q}:null;};
function selectSuggestedPlace(target,place){
 ++searchVersion;++selectionVersion;state.busy=false;state.error=null;state.results=null;state.paths=[];state.path=null;state.lines=[];state.route=null;state.stop=null;state.routeStops=[];state.vehicles=[];state.arrivals=[];
 if(target==='origin'){state.from=place;state.origin=place.name;}else{state.to=place;state.query=place.name;}
 state.focusKey=`place-${Date.now()}`;
 if(state.from&&state.to){search();return;}
 render();document.querySelector(target==='origin'?'#search-input':'#origin-input')?.focus();
}
async function placesFor(query,target,version){const point=coordinateText(query);if(point){if(target==='origin'){state.from=point;state.origin=point.name;}else{state.to=point;state.query=point.name;}return true;}const result=await api(`/api/places?q=${encodeURIComponent(query)}`);if(version!==searchVersion)return false;state.results={kind:'places',target,query,page:result.page,hasMore:result.hasMore,items:result.places};return false;}
async function search(target){
 let firstRoute=null;const version=++searchVersion;++selectionVersion;if(state.mode!=='destination'){state.route=null;state.stop=null;state.vehicles=[];state.arrivals=[];state.routeStops=[];state.liveAt=null;state.vehicleAt=null;state.liveError=null;}state.error=null;state.busy=true;if(state.view!=='map')state.view='explore';state.pane='search';render();
 try{
  if(state.mode==='destination'){
   if(target==='origin'||!state.from){if(!state.origin.trim())throw Object.assign(Error(),{key:'selectOrigin'});if(!await placesFor(state.origin,'origin',version))return;}
   if(!state.to){if(!state.query.trim())throw Object.assign(Error(),{key:'queryRequired'});if(!await placesFor(state.query,'destination',version))return;}
   const result=await api('/api/journeys',postOptions({from:state.from,to:state.to,sort:state.sort}));if(version!==searchVersion)return;
   state.paths=result.journeys;state.journeySource=result.source;state.journeyAt=result.receivedAt;state.results={kind:'journeys'};state.route=null;state.stop=null;state.routeStops=[];state.vehicles=[];state.arrivals=[];
   await selectPath(sorted()[0],false);
  }else{if(!state.query.trim())throw Object.assign(Error(),{key:'queryRequired'});const kind=state.mode==='route'?'routes':'stops';const result=await api(`/api/${kind}?q=${encodeURIComponent(state.query.trim())}`);if(version!==searchVersion)return;state.results={kind,query:state.query.trim(),page:result.page,hasMore:result.hasMore,total:result.total,items:result[kind]};state.route=null;state.stop=null;state.routeStops=[];state.vehicles=[];state.lines=[];state.focusKey=`search-${version}`;if(kind==='routes'&&state.view==='map')firstRoute=result.routes[0]?.id||null;}
 }catch(error){if(version===searchVersion)state.error=error.key||'connectionError';}finally{if(version===searchVersion){state.busy=false;render();}}
 if(firstRoute&&version===searchVersion)await selectRoute(firstRoute);
}
function pickPoint(kind,point){if(kind==='origin'){state.from=point;state.origin=point.name;}else{state.to=point;state.query=point.name;}state.mode='destination';state.error=null;state.focusKey=`point-${Date.now()}`;render();toast(t(kind==='origin'?'pickOrigin':'pickDestination'));}
async function selectPath(path,redraw=true){state.path=path||null;state.lines=(path?.legs||[]).flatMap(l=>l.points?.length?[l.points]:[]);state.focusKey=`path-${Date.now()}`;if(path?.mapObject){try{state.lines=(await api(`/api/geometry?mapObject=${encodeURIComponent(path.mapObject)}`)).lines;}catch(error){toast(t(error.key||'connectionError'));}}if(redraw)render();}
async function selectRoute(id){++searchVersion;const r=[state.route,...state.favorites,...(state.results?.kind==='routes'?state.results.items:[])].find(r=>r?.id===id)||{id,number:state.arrivals.find(a=>a.routeId===id)?.number||id};const version=++selectionVersion;
 state.route=r;loadRouteGroup(r.number);state.stop=null;state.board=null;state.routeStops=[];state.vehicles=[];state.arrivals=[];state.lines=[];state.context=`route:${id}`;loadReviewSummary();const liveView=state.view==='map';if(!liveView)state.view='explore';state.pane=liveView?'map':'search';state.liveAt=null;state.vehicleAt=null;state.liveError=null;state.error=null;if(!(state.results?.kind==='routes'&&state.results.items.some(x=>x.id===id)))state.results={kind:'routes',items:[r]};state.busy=true;render();
 try{const result=await api(`/api/route-stops?id=${encodeURIComponent(id)}`);if(version!==selectionVersion)return;state.routeStops=result.stops;state.focusKey=`route-${id}-${Date.now()}`;}catch(error){if(version===selectionVersion)state.liveError=error.key||'connectionError';}finally{if(version===selectionVersion){const stopError=state.liveError;await refreshLive(version);state.liveError=state.liveError||stopError;state.busy=false;render();}}
}
const storedRides=()=>{try{return JSON.parse(localStorage.getItem('jb.rides')||'[]');}catch{return [];}};
const gameOn=()=>{try{return localStorage.getItem('jb.game')!=='off';}catch{return true;}};
function setGame(on){try{localStorage.setItem('jb.game',on?'on':'off');}catch{}document.documentElement.dataset.game=on?'on':'off';render();}
function rodeBus(no){const stop=state.stop;if(!stop)return;const before=storedRides(),{rides,added}=addRide(before,{no,stopId:stop.id,lat:stop.lat,lng:stop.lng,at:Date.now()});if(!added){toast(t('gameAlready'));return;}try{localStorage.setItem('jb.rides',JSON.stringify(rides));}catch{}const fresh=newStamps(before,rides);toast(fresh.length?t('gameNewStamp',{name:t(`stamp_${fresh[0].replaceAll('-','_')}`)}):t('gameSaved'));}
const stored=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key)??'null')??fallback;}catch{return fallback;}};
const store=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));}catch{}};
const myStops=()=>stored('jb.myStops',[]);
const guideOpen=()=>!stored('jb.guideDone',false);
async function loadHomeLine(){state.homeLine=null;const home=stored('jb.homeStop',null),stop=state.stop;if(!home||!stop||home.id===stop.id)return;try{const line=await api(`/api/board/home?id=${encodeURIComponent(stop.id)}&q=${encodeURIComponent(home.name)}`);if(state.stop?.id===stop.id){state.homeLine=line;const el=document.querySelector('#home-line');if(el)el.innerHTML=homeLineMarkup(line,home.name,e,t);}}catch{}}
function toggleHome(){const stop=state.stop;if(!stop)return;const same=stored('jb.homeStop',null)?.id===stop.id;store('jb.homeStop',same?null:{id:stop.id,name:stop.name});state.homeLine=null;render();}
function toggleStop(){const stop=state.stop;if(!stop)return;const list=myStops(),next=list.some(s=>s.id===stop.id)?list.filter(s=>s.id!==stop.id):[...list,{id:stop.id,name:stop.name,lat:stop.lat,lng:stop.lng}].slice(-5);store('jb.myStops',next);render();}
async function refreshHome(){if(document.hidden||state.view!=='home')return;const list=myStops();await Promise.allSettled(list.map(async s=>{state.homeBoards[s.id]=await api(`/api/board/stop?id=${encodeURIComponent(s.id)}`);}));if(state.view==='home'&&list.length)render();}
function applySimple(){document.documentElement.dataset.simple=stored('jb.simple',false)?'on':'off';}
function routeBoardView(){if(!state.routeStops.length)return '';const age=state.vehicleAt?(Date.now()-Date.parse(state.vehicleAt))/1000:null;const mine=mineOnRoute(),names=new Set(state.routeStops.map(s=>s.name));return `<h3>${t('routeStops')}</h3><p class="muted">${t('stopsNotRoad')}</p>${routeJumpMarkup(t,state.vehicles.some(v=>names.has(v.stop)),!!mine)}${routeBoardMarkup(state.routeStops,state.vehicles,state.route?.number||'',age,mine?.id,e,t)}`;}
function mineOnRoute(){const ids=new Set([state.stop?.id,...myStops().map(s=>s.id)]);return state.routeStops.find(s=>ids.has(s.id))||null;}
