async function shareCard(){const rides=storedRides(),canvas=drawShareCard(document.createElement('canvas'),rides,t);const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));const file=new File([blob],'my-jeju.png',{type:'image/png'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:t('gameTitle')});}catch{}return;}const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='my-jeju.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function openLegStop(name,lat,lng){try{const q=new URLSearchParams({q:name});if(lat&&lng){q.set('lat',lat);q.set('lng',lng);}const stop=await api(`/api/board/find?${q}`);dialog.close();state.view='explore';state.pane='search';await chooseStop(stop);}catch(error){toast(t(error.status===404?'journeyNoStop':error.key||'connectionError'));}}
function todayView(){const d=state.todayData;if(!d)return null;const mine=new Set(state.favorites.map(r=>r.number));return {...d,mine:d.notices.filter(n=>n.numbers.some(no=>mine.has(no)))};}
