async function chooseStop(value){const stop=typeof value==='object'?value:[...state.routeStops,...(state.results?.kind==='stops'?state.results.items:[])].find(s=>s.id===value);if(!stop)return;const version=++selectionVersion;state.stop=stop;state.board=null;state.side=null;state.sideTo='';state.context=`stop:${stop.id}`;state.arrivals=[];state.liveAt=null;state.liveError=null;state.pane='search';state.focusKey=`stop-${stop.id}`;state.homeLine=null;render();loadReviewSummary();loadReports(stop.id);loadHomeLine();await refreshLive(version);if(version===selectionVersion)render();}
async function refreshLive(version=selectionVersion){if(polling.has(version)||document.hidden)return;polling.add(version);const routeId=state.route?.id,stopId=state.stop?.id;try{const jobs=[];if(routeId)jobs.push(api(`/api/live/route?id=${encodeURIComponent(routeId)}`).then(r=>({type:'vehicles',data:r.vehicles,at:r.receivedAt,coverage:r.coverage})));if(stopId)jobs.push(api(`/api/board/stop?id=${encodeURIComponent(stopId)}`).then(r=>({type:'arrivals',data:r.arrivals,at:r.receivedAt,board:r})));const results=await Promise.allSettled(jobs);if(version!==selectionVersion)return;state.liveError=null;for(const result of results){if(result.status==='fulfilled'){state[result.value.type]=result.value.data;state.liveAt=result.value.at;if(result.value.board)state.board=result.value.board;if(result.value.coverage)state.liveCoverage=result.value.coverage;if(result.value.type==='vehicles')state.vehicleAt=result.value.at;}else state.liveError=result.reason.key||'connectionError';}const el=document.querySelector('#live-content');if(el)el.innerHTML=liveContent();const rb=document.querySelector('#route-board');if(rb)rb.innerHTML=routeBoardView();const sr=document.querySelector('#side-result');if(sr&&state.side)sr.innerHTML=sideResultMarkup(state.side,e,t,state.board);const summary=document.querySelector('#map-live-summary');if(summary)summary.innerHTML=liveMapSummary();updateMapData(mapData(),t,chooseStop);}finally{polling.delete(version);}}
